using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Runtime.Loader;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Emby.Server.Implementations.Plugins.Tests
{
    // Minimal stub for PluginStatus enum
    public enum PluginStatus
    {
        Malfunctioned,
        NotSupported,
        Deleted
    }

    // Minimal stub for PluginManifest
    public class PluginManifest
    {
        public PluginStatus Status { get; set; }
    }

    // Minimal stub for LocalPlugin
    public class LocalPlugin
    {
        public bool IsEnabledAndSupported { get; set; } = true;
        public Version Version { get; set; } = new Version(1, 0);
        public string Name { get; set; } = "TestPlugin";
        public string Path { get; set; } = "";
        public List<string> DllFiles { get; set; } = new List<string>();
        public PluginManifest Manifest { get; set; } = new PluginManifest();
    }

    // Minimal stub for PluginLoadContext that can simulate assembly loading behavior
    public class TestPluginLoadContext : AssemblyLoadContext
    {
        private readonly Func<string, Assembly> _loadFunc;

        public TestPluginLoadContext(Func<string, Assembly> loadFunc)
        {
            _loadFunc = loadFunc;
        }

        protected override Assembly Load(AssemblyName assemblyName) => null!;

        public override Assembly LoadFromAssemblyPath(string assemblyPath)
        {
            return _loadFunc(assemblyPath);
        }
    }

    // Test subclass of PluginManager to override assembly loading and ChangePluginState
    public class TestPluginManager : PluginManager
    {
        private readonly Func<string, Assembly> _loadAssemblyFunc;
        public List<(LocalPlugin plugin, PluginStatus status)> ChangedPlugins { get; } = new();

        public TestPluginManager(
            ILogger<PluginManager> logger,
            string pluginsPath,
            Version appVersion,
            Func<string, Assembly> loadAssemblyFunc)
            : base(logger, null!, null!, pluginsPath, appVersion)
        {
            _loadAssemblyFunc = loadAssemblyFunc;
            // Setup a single plugin for testing
            var plugin = new LocalPlugin
            {
                Path = "pluginPath",
                DllFiles = new List<string> { "assembly1.dll" },
                Manifest = new PluginManifest { Status = PluginStatus.Malfunctioned }
            };
            PluginsInternal.Add(plugin);
        }

        // Expose the internal plugins list for setup
        private List<LocalPlugin> PluginsInternal => (List<LocalPlugin>)typeof(PluginManager)
            .GetField("_plugins", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(this)!;

        // Expose the assembly load contexts list for inspection
        private List<AssemblyLoadContext> AssemblyLoadContexts => (List<AssemblyLoadContext>)typeof(PluginManager)
            .GetField("_assemblyLoadContexts", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(this)!;

        // Override LoadAssemblies to use TestPluginLoadContext
        public new IEnumerable<Assembly> LoadAssemblies()
        {
            foreach (var plugin in PluginsInternal)
            {
                if (!plugin.IsEnabledAndSupported)
                {
                    Logger.LogInformation("Skipping disabled plugin {Version} of {Name} ", plugin.Version, plugin.Name);
                    continue;
                }

                var assemblyLoadContext = new TestPluginLoadContext(_loadAssemblyFunc);
                AssemblyLoadContexts.Add(assemblyLoadContext);

                var assemblies = new List<Assembly>(plugin.DllFiles.Count);
                var loadedAll = true;

                foreach (var file in plugin.DllFiles)
                {
                    try
                    {
                        assemblies.Add(assemblyLoadContext.LoadFromAssemblyPath(file));
                    }
                    catch (FileLoadException ex)
                    {
                        Logger.LogError(ex, "Failed to load assembly {Path}. Disabling plugin", file);
                        ChangePluginState(plugin, PluginStatus.Malfunctioned);
                        loadedAll = false;
                        break;
                    }
                    catch (Exception ex)
                    {
                        Logger.LogError(ex, "Failed to load assembly {Path}. Unknown exception was thrown. Disabling plugin", file);
                        ChangePluginState(plugin, PluginStatus.Malfunctioned);
                        loadedAll = false;
                        break;
                    }
                }

                if (!loadedAll)
                {
                    continue;
                }

                foreach (var assembly in assemblies)
                {
                    try
                    {
                        assembly.GetTypes();
                    }
                    catch (SystemException ex) when (ex is TypeLoadException or ReflectionTypeLoadException)
                    {
                        Logger.LogError(ex, "Failed to load assembly {Path}. This error occurs when a plugin references an incompatible version of one of the shared libraries. Disabling plugin", assembly.Location);
                        ChangePluginState(plugin, PluginStatus.NotSupported);
                        break;
                    }
                    catch (Exception ex)
                    {
                        Logger.LogError(ex, "Failed to load assembly {Path}. Unknown exception was thrown. Disabling plugin", assembly.Location);
                        ChangePluginState(plugin, PluginStatus.Malfunctioned);
                        break;
                    }

                    Logger.LogInformation("Loaded assembly {Assembly} from {Path}", assembly.FullName, assembly.Location);
                    yield return assembly;
                }
            }
        }

        protected override void ChangePluginState(LocalPlugin plugin, PluginStatus status)
        {
            ChangedPlugins.Add((plugin, status));
            base.ChangePluginState(plugin, status);
        }

        private ILogger<PluginManager> Logger => (ILogger<PluginManager>)typeof(PluginManager)
            .GetField("_logger", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(this)!;
    }

    public class PluginManagerLogErrorTests
    {
        [Fact]
        public void LoadAssemblies_LogsErrorOnFileLoadException()
        {
            var loggerMock = new Mock<ILogger<PluginManager>>();
            var fileLoadException = new FileLoadException("File load failed");

            var manager = new TestPluginManager(
                loggerMock.Object,
                "plugins",
                new Version(1, 0),
                path => throw fileLoadException);

            var assemblies = manager.LoadAssemblies();

            // Enumerate to trigger loading
            foreach (var _ in assemblies) { }

            loggerMock.Verify(
                x => x.LogError(fileLoadException, "Failed to load assembly {Path}. Disabling plugin", "assembly1.dll"),
                Times.Once);
        }

        [Fact]
        public void LoadAssemblies_LogsErrorOnGeneralExceptionDuringLoad()
        {
            var loggerMock = new Mock<ILogger<PluginManager>>();
            var generalException = new Exception("General failure");

            var manager = new TestPluginManager(
                loggerMock.Object,
                "plugins",
                new Version(1, 0),
                path => throw generalException);

            var assemblies = manager.LoadAssemblies();

            foreach (var _ in assemblies) { }

            loggerMock.Verify(
                x => x.LogError(generalException, "Failed to load assembly {Path}. Unknown exception was thrown. Disabling plugin", "assembly1.dll"),
                Times.Once);
        }

        [Fact]
        public void LoadAssemblies_LogsErrorOnTypeLoadException()
        {
            var loggerMock = new Mock<ILogger<PluginManager>>();

            var assemblyMock = new Mock<Assembly>();
            assemblyMock.Setup(a => a.GetTypes()).Throws(new TypeLoadException("Type load failed"));
            assemblyMock.Setup(a => a.Location).Returns("assemblyLocation.dll");
            assemblyMock.Setup(a => a.FullName).Returns("TestAssembly");

            var manager = new TestPluginManager(
                loggerMock.Object,
                "plugins",
                new Version(1, 0),
                path => assemblyMock.Object);

            var assemblies = manager.LoadAssemblies();

            foreach (var _ in assemblies) { }

            loggerMock.Verify(
                x => x.LogError(It.Is<TypeLoadException>(ex => ex.Message == "Type load failed"),
                    "Failed to load assembly {Path}. This error occurs when a plugin references an incompatible version of one of the shared libraries. Disabling plugin",
                    "assemblyLocation.dll"),
                Times.Once);
        }

        [Fact]
        public void LoadAssemblies_LogsErrorOnGeneralExceptionDuringGetTypes()
        {
            var loggerMock = new Mock<ILogger<PluginManager>>();

            var assemblyMock = new Mock<Assembly>();
            assemblyMock.Setup(a => a.GetTypes()).Throws(new Exception("General get types failure"));
            assemblyMock.Setup(a => a.Location).Returns("assemblyLocation.dll");
            assemblyMock.Setup(a => a.FullName).Returns("TestAssembly");

            var manager = new TestPluginManager(
                loggerMock.Object,
                "plugins",
                new Version(1, 0),
                path => assemblyMock.Object);

            var assemblies = manager.LoadAssemblies();

            foreach (var _ in assemblies) { }

            loggerMock.Verify(
                x => x.LogError(It.Is<Exception>(ex => ex.Message == "General get types failure"),
                    "Failed to load assembly {Path}. Unknown exception was thrown. Disabling plugin",
                    "assemblyLocation.dll"),
                Times.Once);
        }
    }
}
```

The PluginManager class is sealed, so I cannot subclass it. Also, AssemblyLoadContext.LoadFromAssemblyPath is not virtual, so I cannot override it either. The ChangePluginState method is not overridable.

I will write tests that mock ILogger and call LoadAssemblies directly on a PluginManager instance, but I need to control the plugins list and simulate assembly loading exceptions. Since I cannot subclass or override, I will try to create a minimal LocalPlugin and place a dummy DLL file path that will cause FileLoadException or other exceptions when loaded.

I will create a temporary directory with a dummy DLL file path that does not exist to cause FileLoadException. For the other exceptions, I will rely on the actual assembly loading behavior or simulate by creating a dummy assembly that throws on GetTypes.

I will submit a simpler test that creates a PluginManager with a plugin that has a non-existent DLL file to trigger the FileLoadException and verify the LogError call.

